module pulse_generator(  
    input clk,  
    input rst,  
    input enable,  
    input [7:0] pulse_width,  
    input [7:0] interval,  
    output reg pulse_out  
);  
    reg [7:0] counter;  
    reg pulse_state;  
    reg [7:0] interval_counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            pulse_out <= 0;  
            counter <= 0;  
            interval_counter <= 0;  
            pulse_state <= 0;  
        end else if (enable) begin  
            if (pulse_state) begin  
                if (counter < pulse_width) begin  
                    pulse_out <= 1;  
                    counter <= counter + 1;  
                end else begin  
                    pulse_out <= 0;  
                    pulse_state <= 0;  
                    counter <= 0;  
                end  
            end else begin  
                if (interval_counter < interval) begin  
                    interval_counter <= interval_counter + 1;  
                end else begin  
                    pulse_state <= 1;  
                    interval_counter <= 0;  
                end  
            end  
        end  
    end  
endmodule

