module dram_cell(  
    input wire [3:0] data_in,  
    input wire write_enable,  
    input wire read_enable,  
    output reg [3:0] data_out  
);  
    reg [3:0] memory;  

    always @(posedge write_enable or posedge read_enable) begin  
        if (write_enable)  
            memory <= data_in;  
        if (read_enable)  
            data_out <= memory;  
    end  
endmodule

module TFlipFlop(
    input clk,
    input T,
    output reg Q
);
    always @(posedge clk) begin
        if (T)
            Q <= ~Q;
    end
endmodule

