module phase_detector(  
    input clk_a,  
    input clk_b,  
    output reg phase_out  
);  
    reg clk_a_prev;  
    reg clk_b_prev;  

    always @(posedge clk_a or posedge clk_b) begin  
        if (clk_a) clk_a_prev <= 1;  
        else clk_a_prev <= 0;  

        if (clk_b) clk_b_prev <= 1;  
        else clk_b_prev <= 0;  

        // Detect if clk_a leads clk_b  
        if (clk_a_prev && !clk_b_prev)  
            phase_out <= 1;  
        else  
            phase_out <= 0;  
    end  
endmodule

