module convolutional_encoder(  
    input wire clk,  
    input wire reset,  
    input wire data_in,  
    output reg [1:0] data_out  
);  
    reg [1:0] memory; // Stores last two input bits  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            memory <= 2'b00;  
            data_out <= 2'b00;  
        end else begin  
            // Shift memory  
            memory <= {memory[0], data_in};  
            // Calculate output using generator polynomials  
            data_out[0] <= memory[0] ^ memory[1] ^ data_in; // g1 = 111  
            data_out[1] <= memory[1] ^ data_in;             // g2 = 101  
        end  
    end  
endmodule

