module uart_tx (
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLK_FREQ = 50000000;
    localparam BIT_PERIOD = CLK_FREQ / BAUD_RATE;

    reg [3:0] bit_count;
    reg [15:0] clk_count;
    reg [7:0] tx_data;
    reg transmitting;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // idle state
            busy <= 0;
            transmitting <= 0;
            bit_count <= 0;
            clk_count <= 0;
        end else if (start && !busy) begin
            tx_data <= data_in;
            busy <= 1;
            transmitting <= 1;
            tx <= 0; // start bit
            bit_count <= 0;
            clk_count <= 0;
        end else if (transmitting) begin
            clk_count <= clk_count + 1;
            if (clk_count >= BIT_PERIOD) begin
                clk_count <= 0;
                if (bit_count < 8) begin
                    tx <= tx_data[bit_count]; // send data bits
                    bit_count <= bit_count + 1;
                end else if (bit_count == 8) begin
                    tx <= 1; // stop bit
                    bit_count <= bit_count + 1;
                end else begin
                    busy <= 0; // done transmitting
                    transmitting <= 0;
                    tx <= 1; // return to idle state
                end
            end
        end
    end
endmodule

