module watchdog_timer #(parameter TIMEOUT = 4'b1111) (  
    input wire clk,  
    input wire rst_n,  
    input wire clear,  
    output reg timeout,  
    output reg reset  
);  
    reg [3:0] counter;  

    always @(posedge clk or negedge rst_n) begin  
        if (!rst_n) begin  
            counter <= 4'b0000;  
            timeout <= 1'b0;  
            reset <= 1'b0;  
        end else if (clear) begin  
            counter <= 4'b0000;  
            timeout <= 1'b0;  
            reset <= 1'b0;  
        end else begin  
            if (counter < TIMEOUT) begin  
                counter <= counter + 1;  
                timeout <= 1'b0;  
            end else begin  
                timeout <= 1'b1;  
                reset <= 1'b1;  
            end  
        end  
    end  
endmodule

