module PLL (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] freq_in,  
    output reg [7:0] vco_out  
);  

    reg [7:0] phase_error;  
    reg [7:0] loop_filter;  
    reg [7:0] vco_freq;  

    // Simple phase detector 
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase_error <= 8'b0;  
            loop_filter <= 8'b0;  
            vco_out <= 8'b0;  
            vco_freq <= 8'b0;  
        end else begin  
            phase_error <= freq_in - vco_freq;  
            loop_filter <= loop_filter + phase_error;  
            vco_freq <= loop_filter;  
            vco_out <= vco_freq;  
        end  
    end  
endmodule

