      Q <= memory[A];  
  end  
endmodule

module noise_suppression(
    input clk,
    input reset,
    input noisy_signal,
    output reg clean_signal
);
    parameter SILENT = 1'b0, ACTIVE = 1'b1;
    reg state, next_state;
    reg [1:0] silent_counter, active_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= SILENT;
            silent_counter <= 0;
            active_counter <= 0;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            SILENT: begin
                clean_signal = 0;
                if (!noisy_signal)
                    silent_counter = silent_counter + 1;
                else
                    silent_counter = 0;

                if (silent_counter >= 2)
                    next_state = SILENT;  // stay in SILENT
                else if (silent_counter >= 3)
                    next_state = ACTIVE;   // switch to ACTIVE
                else
                    next_state = SILENT;
            end

            ACTIVE: begin
                clean_signal = 1;
                if (noisy_signal)
                    active_counter = active_counter + 1;
                else
                    active_counter = 0;

                if (active_counter >= 2)
                    next_state = ACTIVE;   // stay in ACTIVE
                else if (active_counter >= 3)
                    next_state = SILENT;   // switch to SILENT
                else
                    next_state = ACTIVE;
            end

            default: next_state = SILENT;
        endcase
    end
endmodule

