module rsa_encrypt (
    input clk,
    input rst,
    input [31:0] plaintext,
    input [31:0] e,
    input [31:0] n,
    output reg [31:0] ciphertext
);
    reg [31:0] result;
    reg [31:0] base;
    reg [31:0] exp;
    reg [31:0] mod;
    reg [4:0] state;

    parameter IDLE = 0, CALC = 1, DONE = 2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            result <= 1;
            base <= plaintext;
            exp <= e;
            mod <= n;
            ciphertext <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (exp > 0) begin
                        state <= CALC;
                    end else begin
                        ciphertext <= 0;
                        state <= DONE;
                    end
                end
                CALC: begin
                    if (exp[0] == 1) begin
                        result <= (result * base) % mod;
                    end
                    base <= (base * base) % mod;
                    exp <= exp >> 1;

                    if (exp == 0) begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    ciphertext <= result;
                    state <= IDLE; // Reset to idle for next operation
                end
            endcase
        end
    end
endmodule

module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire [3:0] timeout,  
    output reg reset_out  
);  
    reg [3:0] counter;  
    reg timer_enabled;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 4'b0000;  
            reset_out <= 1'b0;  
            timer_enabled <= 1'b0;  
        end else if (enable) begin  
            timer_enabled <= 1'b1;  
            if (counter < timeout) begin  
                counter <= counter + 1;  
                reset_out <= 1'b0;  
            end else begin  
                reset_out <= 1'b1;  
            end  
        end else begin  
            if (timer_enabled) begin  
                if (counter < timeout)  
                    counter <= counter + 1;  
                else  
                    reset_out <= 1'b1;  
            end  
        end  
    end  
endmodule

