module bubble_sort (
    input clk,
    input rst,
    input start,
    input [15:0] data_in,
    output reg [15:0] sorted_out,
    output reg done
);
    reg [3:0] arr [0:3];
    reg [1:0] i, j;
    reg [3:0] temp;
    reg [2:0] state;

    parameter IDLE = 3'd0, SORT = 3'd1, DONE = 3'd2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sorted_out <= 16'b0;
            done <= 0;
            state <= IDLE;
            i <= 0;
            j <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        arr[0] <= data_in[3:0];
                        arr[1] <= data_in[7:4];
                        arr[2] <= data_in[11:8];
                        arr[3] <= data_in[15:12];
                        i <= 0;
                        j <= 0;
                        state <= SORT;
                    end
                end
                SORT: begin
                    if (i < 3) begin
                        if (j < 3 - i) begin
                            if (arr[j] > arr[j + 1]) begin
                                temp = arr[j];
                                arr[j] = arr[j + 1];
                                arr[j + 1] = temp;
                            end
                            j <= j + 1;
                        end else begin
                            j <= 0;
                            i <= i + 1;
                        end
                    end else begin
                        sorted_out <= {arr[3], arr[2], arr[1], arr[0]};
                        done <= 1;
                        state <= DONE;
                    end
                end
                DONE: begin
                    // Do nothing, wait for reset
                end
            endcase
        end
    end
endmodule

