module non_restoring_divider (
    input [7:0] dividend,
    input [7:0] divisor,
    input start,
    input clk,
    input rst,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [7:0] A; // Accumulator
    reg [7:0] Q; // Quotient
    reg [7:0] M; // Divisor
    reg [3:0] count; // Counter for number of shifts
    reg state; // State variable

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            A <= 8'b0;
            Q <= 8'b0;
            M <= divisor;
            count <= 4'b0;
            done <= 0;
            state <= 0;
        end else if (start) begin
            M <= divisor;
            A <= dividend;
            Q <= 8'b0;
            count <= 4'b0000;
            done <= 0;
            state <= 1;
        end else if (state) begin
            if (count < 8) begin
                // Shift left
                {A, Q} <= {A, Q} << 1;
                A[0] <= 1'b0; // Append 0 to the least significant bit of A
                // Subtract divisor
                if (A >= M) begin
                    A <= A - M;
                    Q[0] <= 1'b1; // Set the quotient bit
                end else begin
                    Q[0] <= 1'b0; // Clear the quotient bit
                end
                count <= count + 1;
            end else begin
                quotient <= Q;
                remainder <= A;
                done <= 1;
                state <= 0;
            end
        end
    end
endmodule

module fractional_n_pll (
    input wire clk,          // Input clock
    input wire reset,        // Reset signal
    input wire [7:0] frac_div_ratio, // Fractional division ratio
    output reg vco_out       // VCO output
);
    reg [7:0] phase_accumulator;
    reg [7:0] vco_cycle_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            phase_accumulator <= 8'b0;
            vco_cycle_count <= 8'b0;
            vco_out <= 1'b0;
        end else begin
            phase_accumulator <= phase_accumulator + frac_div_ratio;
            if (phase_accumulator >= 8'd255) begin
                phase_accumulator <= phase_accumulator - 8'd255;
                vco_cycle_count <= vco_cycle_count + 1;
                vco_out <= ~vco_out; // Toggle VCO output
            end
        end
    end
endmodule

