module adaptive_lms_filter #(
    parameter N = 5,                 // Number of taps
    parameter STEP_SIZE = 8'h1       // Step size for weight adaptation
)(
    input wire clk,
    input wire rst,
    input wire signed [15:0] x,      // Input signal
    input wire signed [15:0] d,      // Desired signal
    output wire signed [15:0] y       // Output signal
);

    reg signed [15:0] w [0:N-1];      // Weights
    reg signed [15:0] y_reg;           // Filter output
    integer i;

    // Initialize weights
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'b0;
            end
        end else begin
            // Calculate output
            y_reg <= 0;
            for (i = 0; i < N; i = i + 1) begin
                y_reg <= y_reg + (w[i] * x);
            end

            // Update weights
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= w[i] + (STEP_SIZE * (d - y_reg) * x);
            end
        end
    end

    assign y = y_reg;
endmodule

