module crc5 (
    input wire clk,
    input wire reset,
    input wire data_in,
    input wire data_valid,
    output reg [4:0] crc_out
);
    reg [4:0] crc;

    // Polynomial coefficients for x^5 + x^2 + 1
    localparam POLY = 5'b100101;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            crc <= 5'b0;
        end else if (data_valid) begin
            crc[0] <= data_in ^ crc[4];
            crc[1] <= crc[0];
            crc[2] <= crc[1];
            crc[3] <= crc[2];
            crc[4] <= crc[3] ^ (data_in ? POLY[4] : 1'b0);
        end
    end

    always @(posedge clk) begin
        if (data_valid) begin
            crc_out <= crc;
        end
    end
endmodule

