module watchdog_timer #(parameter TIMEOUT = 10) (  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    output reg timeout_signal  
);  
    reg [3:0] counter; // 4-bit counter for timeout up to 15  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout_signal <= 0;  
        end else if (enable) begin  
            if (counter < TIMEOUT) begin  
                counter <= counter + 1;  
                timeout_signal <= 0;  
            end else begin  
                timeout_signal <= 1;  
            end  
        end  
    end  
endmodule

module divider (
    input [7:0] dividend,
    input [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder
);

always @(*) begin
    if (divisor == 0) begin
        quotient = 8'b0;
        remainder = 8'b0;
    end else begin
        quotient = dividend / divisor;
        remainder = dividend % divisor;
    end
end

endmodule

