module fractional_n_pll (
    input wire clk_ref,           // Reference clock input
    input wire reset,            // Reset signal
    input wire [7:0] frac_value, // Fractional value for frequency tuning
    output reg clk_out           // Output clock
);

    reg [15:0] phase_accumulator; // Phase accumulator
    reg [15:0] vco_counter;        // VCO counter
    reg [7:0] vco_divider;         // VCO divider to tune the output clock frequency

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            phase_accumulator <= 16'd0;
            vco_counter <= 16'd0;
            clk_out <= 0;
            vco_divider <= 8'd1; // Default divider value
        end else begin
            phase_accumulator <= phase_accumulator + frac_value;

            // VCO operation: toggle output clock based on vco_counter
            if (vco_counter >= vco_divider) begin
                clk_out <= ~clk_out;
                vco_counter <= 16'd0;
            end else begin
                vco_counter <= vco_counter + 1;
            end
        end
    end
endmodule

