module divider (
    input wire clk,
    input wire start,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [7:0] temp_dividend;
    reg [7:0] temp_quotient;
    reg [4:0] count; // To count down from 8 to 0
    reg in_process;

    always @(posedge clk) begin
        if (start) begin
            temp_dividend <= dividend;
            temp_quotient <= 8'b0;
            remainder <= 8'b0;
            count <= 8;
            in_process <= 1'b1;
            done <= 1'b0;
        end else if (in_process) begin
            if (count > 0) begin
                temp_quotient <= {temp_quotient[6:0], 1'b0}; // Shift left quotient
                remainder <= {remainder[6:0], temp_dividend[7]}; // Shift left remainder
                temp_dividend <= {temp_dividend[6:0], 1'b0}; // Shift left dividend
                if (remainder >= divisor) begin
                    remainder <= remainder - divisor;
                    temp_quotient[0] <= 1'b1; // Set the LSB of quotient
                end
                count <= count - 1;
            end else begin
                quotient <= temp_quotient;
                in_process <= 1'b0;
                done <= 1'b1;
            end
        end
    end
endmodule

